const TAIL_PATH = 'M400,342 C436,322 462,272 470,204 C448,236 420,244 386,218Z';

// The still wing and the gap it cuts out of the body and tail, in the bird's
// own coordinates. Generated by scripts/kordi-app-icons/flyingBirdCutout.mjs.
export const KORDI_BIRD_STILL_WING_PATH = 'M296.8,261.8 C319.5,214.5 391.7,180.1 447.5,194.7 C418.6,240.4 345.5,273 296.8,261.8Z';
export const KORDI_BIRD_BODY_GAP_PATH = 'M282.8,261.8 283,259.1 283.8,256.5 288.2,248.2 291.8,242.5 300.9,230.8 309.5,221.9 321.3,211.8 333.5,203.3 347.5,195.5 360.6,189.5 368.1,195.8 375.2,202.8 381.8,210.2 387.8,217.9 393.2,226.1 397.9,234.5 402,243.3 405.4,252 386.7,261.7 376.1,266.2 367.2,269.4 355.6,272.8 346.7,274.9 337.8,276.5 326.3,277.7 317.7,278 309.4,277.7 298.7,276.5 291.4,274.8 289,273.5 286.9,271.7 285.1,269.6 283.8,267.2 283,264.6Z';
export const KORDI_BIRD_TAIL_GAP_PATH = 'M412.6,247.6 402.8,253.5 391.3,259.5 387.1,218.8 398.5,226.2 404.5,229.1 410.4,231.3 416.1,232.7 421.7,233.4 427.2,233.4 432.4,232.8 421.9,241.1Z';

// The Kordi bird in flight. Geometry matches scripts/kordi-app-icons/icons.mjs;
// the wing is a separate piece outlined in the background color so it reads
// above the body while it flaps (see `.app-kordi-flying-bird` in the auth gate CSS).
// `cutout` draws a still bird whose wing gap is a hole in the body path, so
// the gap shows whatever is behind the bird, such as a translucent window.
export function KordiFlyingBird({ className, cutout = false }: { className?: string; cutout?: boolean }) {
  return (
    <svg
      className={['app-kordi-flying-bird', cutout ? 'app-kordi-flying-bird-cutout' : '', className ?? ''].filter(Boolean).join(' ')}
      viewBox="0 0 512 512"
      aria-hidden="true"
      focusable="false"
    >
      <g transform="translate(256,250) scale(0.94) translate(-270,-292)">
        <g className="app-kordi-flying-bird-body">
          <path className="app-kordi-flying-bird-beak" d="M120,276 L82,294 L120,312Z" strokeWidth="12" strokeLinejoin="round" />
          <path
            className="app-kordi-flying-bird-fill"
            fillRule="evenodd"
            d={cutout ? `${BODY_PATH} ${EYE_PATH} ${KORDI_BIRD_BODY_GAP_PATH}` : `${BODY_PATH} ${EYE_PATH}`}
          />
          <path
            className="app-kordi-flying-bird-fill"
            fillRule="evenodd"
            d={cutout ? `${TAIL_PATH} ${KORDI_BIRD_TAIL_GAP_PATH}` : TAIL_PATH}
            // A stroke would draw the tail outline across the gap.
            strokeWidth={cutout ? 0 : 4}
            strokeLinejoin="round"
          />
          {cutout ? (
            <path className="app-kordi-flying-bird-wing" d={KORDI_BIRD_STILL_WING_PATH} />
          ) : (
            <g transform="translate(296,262)">
              <path className="app-kordi-flying-bird-wing" d={WING_PATH} strokeWidth={14} strokeLinejoin="round" />
            </g>
          )}
        </g>
      </g>
    </svg>
  );
}
